CREATE TABLE mUser (id_user VARCHAR(32) PRIMARY KEY, nama_user NVARCHAR(250) NOT NULL, username VARCHAR(40) NOT NULL UNIQUE, password VARCHAR(250) NOT NULL, jabatan VARCHAR(20) NOT NULL CHECK (jabatan IN ('Admin','Kasir','Kepala')), telp_user VARCHAR(30) NOT NULL, status_user VARCHAR(20) NOT NULL CHECK (status_user IN ('Aktif','Tidak Aktif')));
CREATE TABLE mCustomer (id_customer VARCHAR(32) PRIMARY KEY, nama_customer NVARCHAR(250) NOT NULL, telp_customer VARCHAR(30) NOT NULL, status_customer VARCHAR(20) NOT NULL CHECK (status_customer IN ('Aktif','Tidak Aktif')));
CREATE TABLE mSupplier (id_supplier VARCHAR(32) PRIMARY KEY, nama_supplier NVARCHAR(250) NOT NULL, telp_supplier VARCHAR(30) NOT NULL, alamat NVARCHAR(250) NOT NULL, status_supplier VARCHAR(20) NOT NULL CHECK (status_supplier IN ('Aktif','Tidak Aktif')));
CREATE TABLE mKategori (id_kategori VARCHAR(32) PRIMARY KEY, nama_kategori NVARCHAR(250) NOT NULL, keterangan NVARCHAR(250) NOT NULL);
CREATE TABLE mObat (id_obat VARCHAR(32) PRIMARY KEY, nama_obat NVARCHAR(250) NOT NULL, id_kategori VARCHAR(32) NOT NULL REFERENCES mKategori(id_kategori), kandungan NVARCHAR(250) NOT NULL, jenis NVARCHAR(250) NOT NULL, dosis NVARCHAR(250) NOT NULL, exp_date DATE NOT NULL, stok INT NOT NULL CHECK (stok BETWEEN 0 AND 1000000), harga DECIMAL(18,2) NOT NULL CHECK (harga>=0));
CREATE TABLE mResep (id_resep VARCHAR(32) PRIMARY KEY, id_customer VARCHAR(32) NOT NULL REFERENCES mCustomer(id_customer), nama_dokter NVARCHAR(250) NOT NULL, praktek NVARCHAR(250) NOT NULL, kandungan NVARCHAR(250) NOT NULL, tgl_input DATE NOT NULL);
CREATE TABLE tbTrPembelian (id_pembelian VARCHAR(32) PRIMARY KEY, id_supplier VARCHAR(32) NOT NULL REFERENCES mSupplier(id_supplier), tgl_pembelian DATE NOT NULL, total_harga_beli DECIMAL(18,2) NOT NULL CHECK (total_harga_beli>=0));
CREATE TABLE tbDetailPembelian (id_pembelian VARCHAR(32) NOT NULL REFERENCES tbTrPembelian(id_pembelian), id_obat VARCHAR(32) NOT NULL REFERENCES mObat(id_obat), jumlah_obat INT NOT NULL CHECK (jumlah_obat>0), jumlah_harga DECIMAL(18,2) NOT NULL CHECK (jumlah_harga>=0), PRIMARY KEY(id_pembelian,id_obat));
CREATE TABLE tbTrPenjualan (id_penjualan VARCHAR(32) PRIMARY KEY, id_resep VARCHAR(32) NULL REFERENCES mResep(id_resep), tgl_penjualan DATE NOT NULL, total_harga_jual DECIMAL(18,2) NOT NULL CHECK (total_harga_jual>=0));
CREATE TABLE tbDetailPenjualan (id_penjualan VARCHAR(32) NOT NULL REFERENCES tbTrPenjualan(id_penjualan), id_obat VARCHAR(32) NOT NULL REFERENCES mObat(id_obat), jumlah_obat INT NOT NULL CHECK (jumlah_obat>0), jumlah_harga DECIMAL(18,2) NOT NULL CHECK (jumlah_harga>=0), PRIMARY KEY(id_penjualan,id_obat));
